/**
 * The Astrometrics Studio's Starters gallery: every starter has a picture
 * (generated by `npm run astro:pictures`) and a one-line summary, there are
 * no pictures for starters that are gone, and the gallery helpers turn a
 * starter's params into form fields and say what it adds.
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { existsSync, readdirSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { STARTERS } from '../../src/core/astrometrics/starters/index.js';
import { starterPicture, starterParamSchema, starterParamChoices, starterParamValues, starterAdds, PICTURE_BASE } from '../../src/editor/dialogs/astro-studio/starter-gallery.js';
import { fieldKind } from '../../src/editor/dialogs/astro-studio/schema-fields.js';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
// the source (the build copies it to custom_components/lcards/images/)
const DIR = join(ROOT, 'src/assets/images/astro-studio');
const fileOf = (/** @type {string} */ url) => join(DIR, url.slice(PICTURE_BASE.length));

test('every starter has its picture (npm run astro:pictures), and no picture is left over', () => {
  const missing = STARTERS.filter((s) => !existsSync(fileOf(starterPicture(s.id)))).map((s) => s.id);
  assert.deepEqual(missing, [], 'run npm run astro:pictures for these starters');
  const wanted = new Set(STARTERS.map((s) => starterPicture(s.id).slice(PICTURE_BASE.length)));
  const stray = readdirSync(DIR).filter((f) => f.startsWith('starter-') && !wanted.has(f));
  assert.deepEqual(stray, []);
});

test('every starter has a one-line summary for its tile', () => {
  for (const s of STARTERS) {
    assert.ok(s.summary, `${s.id} has no summary`);
    assert.ok(s.summary.length <= 80, `${s.id}: summary is ${s.summary.length} characters`);
    assert.ok(!/[.—]$/.test(s.summary), `${s.id}: a summary is a phrase, not a sentence`);
  }
});

test('starter params become form fields: numbers, point pickers, dropdowns and text', () => {
  for (const s of STARTERS) {
    const schema = starterParamSchema(s);
    for (const p of s.params) {
      const kind = fieldKind(schema[p.key], p.key);
      const want = p.type === 'number' ? 'number' : p.type === 'point' ? 'pointRef' : p.options?.length && !p.custom ? 'enum' : 'text';
      assert.equal(kind, want, `${s.id}.${p.key}`);
      assert.equal(schema[p.key]['x-ui-hints'].label, p.label);
    }
  }
  const planet = STARTERS.find((s) => s.id === 'planet');
  assert.ok(planet);
  assert.ok(starterParamChoices(planet).look.includes('gas_giant'));
  assert.equal(starterParamValues(planet, { moons: 4 }).moons, 4);
  assert.equal(starterParamValues(planet).orbit, 40);
});

test('what a starter adds, in words', () => {
  const planet = STARTERS.find((s) => s.id === 'planet');
  assert.ok(planet);
  assert.match(starterAdds(planet), /^\d+ points, \d+ objects$/);
  assert.notEqual(starterAdds(planet, { moons: 0 }), starterAdds(planet, { moons: 4 }));
});
